          language: 'html',
          code: "<h1>Dogs Table</h1>\n<table>\n  <tr>\n    <td>&nbsp;</td>\n    <td>Knocky</td>\n    <td>Flor</td>\n    <td>Ella</td>\n    <td>Juan</td>\n  </tr>\n  <tr>\n    <td>Breed</td>\n    <td>Jack Russell</td>\n    <td>Poodle</td>\n    <td>Streetdog</td>\n    <td>Cocker Spaniel</td>\n  </tr>\n  <tr>\n    <td>Age</td>\n    <td>16</td>\n    <td>9</td>\n    <td>10</td>\n    <td>5</td>\n  </tr>\n  <tr>\n    <td>Owner</td>\n    <td>Mother-in-law</td>\n    <td>Me</td>\n    <td>Me</td>\n    <td>Sister-in-law</td>\n  </tr>\n  <tr>\n    <td>Eating Habits</td>\n    <td>Eats everyone's leftovers</td>\n    <td>Nibbles at food</td>\n    <td>Hearty eater</td>\n    <td>Will eat till he explodes</td>\n  </tr>\n</table>",
